<script setup>
import {ref,computed,watch,onMounted,onUnmounted,nextTick} from 'vue';
import {useRoute,useRouter} from 'vue-router';
import {marked} from 'marked';
import sanitizeHtml from 'sanitize-html';
const route=useRoute(),router=useRouter();
const user=ref(null),csrf=ref(''),busy=ref(false),loading=ref(true),error=ref(''),success=ref(''),unread=ref(0);
const result=ref({items:[],total:0}),overview=ref(null),trend=ref([]),detail=ref(null),reason=ref(''),edit=ref(null);
const page=ref(1),q=ref(''),status=ref(''),notificationType=ref(''),onlyUnread=ref(false);
const area=computed(()=>route.path==='/me/notifications'?'notifications':route.path.split('/')[2]||'overview');
const titles={overview:'平台概览',articles:'文章审核',users:'用户管理',comments:'评论治理',taxonomy:'分类与标签',notifications:'站内通知'};
const labels={DRAFT:'草稿',PENDING:'待审核',PUBLISHED:'已发布',REJECTED:'已驳回',OFFLINE:'已下架',ACTIVE:'正常',DISABLED:'已禁用',VISIBLE:'可见',HIDDEN:'已隐藏',DELETED:'已删除',COMMENT:'新评论',REPLY:'新回复',APPROVED:'审核通过'};
const taxonomy=ref({categories:[],tags:[]});
const html=computed(()=>sanitizeHtml(marked.parse(detail.value?.bodyMarkdown||'',{renderer:Object.assign(new marked.Renderer(),{html:()=>''})})));
const points=computed(()=>trend.value.map((r,i)=>`${25+i*65},${125-Number(r.count)/Math.max(1,...trend.value.map(d=>Number(d.count)))*95}`).join(' '));
let generation=0,timer,previousFocus;
watch(edit,async value=>{if(value){previousFocus=document.activeElement;await nextTick();document.querySelector('.ops-modal [autofocus], .ops-modal input, .ops-modal button')?.focus();}else if(previousFocus?.isConnected)previousFocus.focus();});
function trapFocus(event){if(event.key!=='Tab')return;const nodes=[...event.currentTarget.querySelectorAll('input,textarea,select,button')].filter(e=>!e.disabled);if(!nodes.length)return;const first=nodes[0],last=nodes.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}
async function api(path,method='GET',body){const r=await fetch('/api'+path,{method,credentials:'same-origin',headers:{...(method!=='GET'?{'X-CSRF-Token':csrf.value,'Content-Type':'application/json'}:{})},...(body===undefined?{}:{body:JSON.stringify(body)})});const data=await r.json();if(!r.ok){if(r.status===401){user.value=null;router.replace({path:'/login',query:{next:route.fullPath}});}throw new Error(data.message||'请求失败');}return data.data;}
async function counts(){if(user.value)unread.value=Number((await api('/me/notifications/unread-count')).count);}
async function load(){const current=++generation;loading.value=true;error.value='';detail.value=null;
  try{
    csrf.value=(await api('/auth/csrf')).token;user.value=await api('/auth/me');
    if(!user.value){router.replace({path:'/login',query:{next:route.fullPath}});return;}
    if(area.value!=='notifications'&&user.value.role!=='ADMIN'){error.value='当前账号没有管理权限。';return;}
    const params=new URLSearchParams({page:String(page.value),pageSize:'10'});if(q.value)params.set('q',q.value);if(status.value)params.set('status',status.value);
    let data;
    if(area.value==='overview'){const [o,t]=await Promise.all([api('/admin/overview'),api('/admin/statistics/publications')]);if(current===generation){overview.value=o;trend.value=t;}}
    else if(area.value==='taxonomy'){const [categories,tags]=await Promise.all([api('/admin/categories'),api('/admin/tags')]);if(current===generation)taxonomy.value={categories,tags};}
    else {if(area.value==='notifications'){if(onlyUnread.value)params.set('unread','1');if(notificationType.value)params.set('type',notificationType.value);}data=await api((area.value==='notifications'?'/me/notifications':'/admin/'+area.value)+'?'+params);if(current===generation)result.value=data;}
    await counts();
  }catch(e){if(current===generation)error.value=e.message;}finally{if(current===generation)loading.value=false;}
}
async function act(fn){if(busy.value)return;busy.value=true;error.value='';success.value='';try{await fn();success.value='操作已完成';await load();}catch(e){error.value=e.message;}finally{busy.value=false;}}
async function inspect(id){error.value='';try{detail.value=await api('/admin/articles/'+id);reason.value='';await nextTick();document.querySelector('.ops-detail')?.scrollIntoView({behavior:'smooth',block:'start'});}catch(e){error.value=e.message;}}
function review(action){const d=detail.value;return act(()=>api('/admin/articles/'+d.id+'/review','POST',{action,reason:reason.value,version:d.version}));}
function offline(){const d=detail.value;return act(()=>api('/admin/articles/'+d.id+'/offline','POST',{reason:reason.value,version:d.version}));}
function openEdit(kind,item=null){edit.value={kind,...(item?{...item,enabled:Boolean(item.enabled)}:{name:'',enabled:true,sortOrder:0})};reason.value='';}
function saveTaxonomy(){const e=edit.value;return act(async()=>{await api('/admin/'+e.kind+(e.id?'/'+e.id:''),e.id?'PATCH':'POST',{name:e.name,enabled:e.enabled,sortOrder:Number(e.sortOrder)});edit.value=null;});}
function confirmAction(kind,item){edit.value={kind,item};reason.value='';}
function execute(){const e=edit.value;return act(async()=>{if(e.kind==='user')await api('/admin/users/'+e.item.id+'/status','PATCH',{status:e.item.status==='ACTIVE'?'DISABLED':'ACTIVE',reason:reason.value});else if(e.kind==='comment')await api('/admin/comments/'+e.item.id+'/status','PATCH',{status:'HIDDEN',reason:reason.value});else await api('/admin/'+e.kind.replace('delete-','')+'/'+e.item.id,'DELETE');edit.value=null;});}
async function openNotification(n){await act(async()=>{await api('/me/notifications/'+n.id+'/read','PATCH');});if(error.value)return;if(n.articleId){try{await api('/articles/'+n.articleId);router.push({path:'/articles/'+n.articleId,query:n.commentId?{commentId:n.commentId}:{},hash:n.commentId?'#comment-'+n.commentId:''});}catch(e){error.value=e.message==='文章不存在或已不可用'?'消息已标为已读，该文章当前未公开或已不可用。':e.message;}}}
function filter(){page.value=1;load();}
function changePage(delta){page.value+=delta;load();}
async function logout(){if(busy.value)return;busy.value=true;try{await api('/auth/logout','POST');user.value=null;await router.push('/login');}catch(e){error.value=e.message;}finally{busy.value=false;}}
watch(()=>route.path,()=>{page.value=1;q.value='';status.value='';edit.value=null;success.value='';load();});
onMounted(()=>{load();timer=setInterval(()=>counts().catch(()=>{}),30000);});onUnmounted(()=>{generation++;clearInterval(timer);});
</script>

<template>
  <div class="ops-shell">
    <aside class="ops-nav"><RouterLink to="/" class="ops-brand">OnlyCampus<span>校园创作与成长</span></RouterLink>
      <nav aria-label="管理导航"><RouterLink to="/">← 返回发现</RouterLink>
        <template v-if="user?.role==='ADMIN'"><RouterLink v-for="item in ['overview','articles','users','comments','taxonomy']" :key="item" :to="item==='overview'?'/admin':'/admin/'+item" :class="{active:area===item}">{{titles[item]}}</RouterLink></template>
        <RouterLink to="/me/notifications" :class="{active:area==='notifications'}">站内通知 <span v-if="unread" class="ops-badge">{{unread}}</span></RouterLink>
      </nav><div class="ops-account"><strong>{{user?.nickname}}</strong><small>{{user?.role==='ADMIN'?'运营管理员':'校园用户'}}</small><button @click="logout" :disabled="busy">退出登录</button></div>
    </aside>
    <main class="ops-main"><header class="ops-heading"><div><p>ONLYCAMPUS / {{area==='notifications'?'消息中心':'运营工作台'}}</p><h1>{{titles[area]}}</h1></div><button @click="load" :disabled="busy||loading">刷新</button></header>
      <p v-if="error" class="ops-alert" role="alert">{{error}}</p><p v-if="success" class="ops-success" role="status">{{success}}</p>
      <p v-if="loading" class="ops-empty" role="status">正在加载…</p>
      <template v-else-if="user && (user.role==='ADMIN'||area==='notifications')">
        <template v-if="area==='overview' && overview"><section class="ops-metrics"><article v-for="(label,key) in {users:'注册用户',published:'公开文章',pending:'等待审核',comments:'可见评论'}" :key="key"><span>{{label}}</span><strong>{{overview[key]}}</strong></article></section>
          <section class="ops-card"><div class="ops-section-title"><div><h2>近7日首次发布</h2><p>按北京时间统计，每篇文章首次发布计入一次。</p></div><RouterLink to="/admin/articles">处理文章 →</RouterLink></div>
            <svg class="ops-chart" viewBox="0 0 440 150" role="img" aria-label="近7日首次发布趋势，详细数值见下表"><path d="M25 125H415 M25 78H415 M25 30H415" stroke="#e2e8e3" fill="none"/><polyline :points="points" fill="none" stroke="#2f5d50" stroke-width="3"/><circle v-for="(point,i) in points.split(' ')" :key="i" :cx="point.split(',')[0]" :cy="point.split(',')[1]" r="4" fill="#c67840"/></svg>
            <div class="ops-table-wrap"><table><caption class="visually-hidden">每日首次发布文章数</caption><thead><tr><th v-for="d in trend" :key="d.day" scope="col">{{d.day.slice(5)}}</th></tr></thead><tbody><tr><td v-for="d in trend" :key="d.day">{{d.count}} 篇</td></tr></tbody></table></div>
          </section></template>

        <template v-else-if="area==='taxonomy'"><section v-for="kind in ['categories','tags']" :key="kind" class="ops-card"><div class="ops-section-title"><h2>{{kind==='categories'?'公共分类':'公共标签'}}</h2><button @click="openEdit(kind)">＋ 新建</button></div><p class="ops-muted">已被文章引用的条目请停用，历史内容仍保留。</p><div class="ops-table-wrap"><table><thead><tr><th>名称</th><th>状态</th><th>排序</th><th>操作</th></tr></thead><tbody><tr v-for="item in taxonomy[kind]" :key="item.id"><td>{{item.name}}</td><td>{{item.enabled?'启用':'停用'}}</td><td>{{item.sortOrder}}</td><td class="ops-actions"><button @click="openEdit(kind,item)">编辑</button><button @click="confirmAction('delete-'+kind,item)">删除</button></td></tr></tbody></table></div></section></template>

        <template v-else><section class="ops-card">
          <form class="ops-filters" @submit.prevent="filter">
            <label v-if="['articles','comments'].includes(area)">关键词<input v-model="q" :placeholder="area==='articles'?'搜索文章标题':'搜索评论内容'" maxlength="100"></label>
            <label v-if="area==='articles'">文章状态<select v-model="status"><option value="">全部状态</option><option v-for="s in ['PENDING','PUBLISHED','REJECTED','OFFLINE','DRAFT']" :key="s" :value="s">{{labels[s]}}</option></select></label>
            <template v-if="area==='notifications'"><label>通知类型<select v-model="notificationType"><option value="">全部类型</option><option v-for="s in ['COMMENT','REPLY','APPROVED','REJECTED','OFFLINE']" :key="s" :value="s">{{labels[s]}}</option></select></label><label class="ops-check"><input type="checkbox" v-model="onlyUnread">仅看未读</label><button type="button" @click="act(()=>api('/me/notifications/read-all','POST'))" :disabled="busy||!unread">全部已读</button></template>
            <button v-if="area!=='users'" type="submit">筛选</button>
          </form>
          <p v-if="!result.items.length" class="ops-empty">{{area==='notifications'?'暂时没有符合条件的消息':'暂无符合条件的记录'}}</p>
          <div v-else-if="area==='notifications'" class="ops-messages"><article v-for="n in result.items" :key="n.id" :class="{unread:!n.readAt}"><div><span class="ops-state">{{labels[n.type]||n.type}}</span><small>{{new Date(n.createdAt).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'})}}</small><p>{{n.summary}}</p></div><div class="ops-actions"><button @click="openNotification(n)" :disabled="busy">查看</button><button v-if="!n.readAt" @click="act(()=>api('/me/notifications/'+n.id+'/read','PATCH'))" :disabled="busy">标为已读</button></div></article></div>
          <div v-else class="ops-table-wrap"><table><thead><tr><th>{{area==='users'?'账号':area==='articles'?'文章':'评论内容'}}</th><th>{{area==='users'?'昵称':'作者'}}</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="item in result.items" :key="item.id"><td>{{item.username||item.title||item.content}}</td><td>{{item.nickname||item.author}}<small v-if="item.role==='ADMIN'">（管理员）</small></td><td><span class="ops-state">{{labels[item.status]||item.status}}</span><span v-if="item.featured"> · 精选</span></td><td class="ops-actions">
            <template v-if="area==='articles'"><button @click="inspect(item.id)">查看处理</button><button v-if="item.status==='PUBLISHED'" @click="act(()=>api('/admin/articles/'+item.id+'/featured','PATCH',{featured:!item.featured}))" :disabled="busy">{{item.featured?'取消精选':'设为精选'}}</button></template>
            <button v-if="area==='users'&&item.role!=='ADMIN'" @click="confirmAction('user',item)">{{item.status==='ACTIVE'?'禁用':'恢复'}}</button>
            <button v-if="area==='comments'&&item.status==='VISIBLE'" @click="confirmAction('comment',item)">隐藏</button>
          </td></tr></tbody></table></div>
          <nav class="ops-pagination" aria-label="分页"><span>共 {{result.total}} 条 · 第 {{page}} 页</span><button :disabled="page<=1||busy" @click="changePage(-1)">上一页</button><button :disabled="page*10>=result.total||busy" @click="changePage(1)">下一页</button></nav>
        </section></template>

        <section v-if="detail" class="ops-card ops-detail" aria-label="文章处理"><div class="ops-section-title"><div><p class="ops-muted">{{detail.author}} · {{labels[detail.status]}}</p><h2>{{detail.title}}</h2></div><button @click="detail=null">关闭</button></div><p>{{detail.summary}}</p><div class="article-body" v-html="html"></div>
          <form v-if="['PENDING','PUBLISHED'].includes(detail.status)" @submit.prevent="detail.status==='PENDING'?review('APPROVE'):offline()"><label>处理说明<textarea v-model="reason" maxlength="300" rows="3" :required="detail.status==='PUBLISHED'" placeholder="驳回或下架时须填写2至300字原因"></textarea></label><div class="ops-actions"><button type="submit" class="ops-primary" :disabled="busy">{{detail.status==='PENDING'?'审核通过':'确认下架'}}</button><button v-if="detail.status==='PENDING'" type="button" @click="review('REJECT')" :disabled="busy||reason.trim().length<2">驳回修改</button></div></form>
          <h3>审核历史</h3><p v-if="!detail.history.length" class="ops-muted">暂无审核记录</p><p v-for="(h,i) in detail.history" :key="i">{{labels[h.fromStatus]}} → {{labels[h.toStatus]}}：{{h.reason||'通过'}} <small>{{new Date(h.createdAt).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'})}}</small></p>
        </section>
      </template>
    </main>
    <div v-if="edit" class="ops-modal-backdrop" @keydown.esc="edit=null"><section class="ops-modal" role="dialog" aria-modal="true" aria-labelledby="ops-dialog-title" @keydown="trapFocus"><h2 id="ops-dialog-title">{{['categories','tags'].includes(edit.kind)?'编辑条目':edit.kind.startsWith('delete-')?'删除未引用条目':edit.kind==='user'?'调整账号状态':'隐藏违规评论'}}</h2><p v-if="error" class="ops-alert" role="alert">{{error}}</p>
      <form v-if="['categories','tags'].includes(edit.kind)" @submit.prevent="saveTaxonomy"><label>名称<input v-model="edit.name" required maxlength="50" autofocus></label><label>排序<input v-model="edit.sortOrder" type="number" min="-100000" max="100000" required></label><label class="ops-check"><input type="checkbox" v-model="edit.enabled">启用</label><div class="ops-actions"><button type="submit" class="ops-primary" :disabled="busy">保存</button><button type="button" @click="edit=null">取消</button></div></form>
      <form v-else @submit.prevent="execute"><p>{{edit.item.name||edit.item.username||edit.item.content}}</p><label v-if="!edit.kind.startsWith('delete-')">操作原因<textarea v-model="reason" minlength="2" maxlength="300" required autofocus></textarea></label><p v-else>仅未被文章引用的条目可删除。</p><div class="ops-actions"><button class="ops-primary" type="submit" :disabled="busy">确认操作</button><button type="button" @click="edit=null">取消</button></div></form>
    </section></div>
  </div>
</template>

<style>
.ops-shell{display:grid;grid-template-columns:224px minmax(0,1fr);max-width:1400px;min-height:100vh;margin:auto}.ops-nav{padding:34px 24px;border-right:1px solid #dfe5df;display:flex;flex-direction:column;gap:34px;background:#f2f5ef}.ops-brand{font-size:23px;font-weight:750;color:#2f5d50}.ops-brand span{display:block;font-size:12px;font-weight:400;margin-top:9px;color:#657267}.ops-nav nav{display:flex;flex-direction:column;gap:8px}.ops-nav nav a{padding:12px 14px;border-radius:9px;font-size:14px}.ops-nav nav a.active,.ops-nav nav a:hover{background:#dfe9df;color:#244d40}.ops-account{margin-top:auto;display:grid;gap:10px}.ops-account small,.ops-muted{color:#66766a}.ops-main{padding:38px 42px;max-width:none;width:100%;min-width:0}.ops-heading,.ops-section-title{display:flex;align-items:center;justify-content:space-between;gap:16px}.ops-heading{margin-bottom:30px}.ops-heading p{font-size:11px;letter-spacing:.1em;color:#66766a;margin:0 0 12px}.ops-heading h1{font-size:29px;margin:0}.ops-shell button{border:1px solid #ccd8ce;background:white;color:#2f5d50;border-radius:8px;padding:9px 13px;min-height:40px}.ops-shell .ops-primary{background:#2f5d50;color:white;border-color:#2f5d50}.ops-card{background:white;border:1px solid #dfe5df;border-radius:14px;padding:24px;margin-bottom:24px;min-width:0}.ops-card h2{font-size:19px;margin:0}.ops-section-title p{font-size:13px;color:#66766a;line-height:1.6}.ops-section-title a{font-size:13px;color:#2f5d50;white-space:nowrap}.ops-metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px;margin-bottom:24px}.ops-metrics article{padding:22px;border:1px solid #dfe5df;border-radius:12px;background:white}.ops-metrics span{font-size:13px;color:#66766a}.ops-metrics strong{display:block;font-size:34px;margin-top:16px;font-weight:650}.ops-chart{display:block;width:100%;max-height:260px;margin:20px auto}.ops-table-wrap{overflow-x:auto}.ops-shell table{width:100%;border-collapse:collapse;text-align:left;font-size:13px;line-height:1.65}.ops-shell th{background:#f1f5f0;font-size:12px;color:#52665a;font-weight:600;white-space:nowrap}.ops-shell th,.ops-shell td{padding:13px 12px;border-bottom:1px solid #e4e9e3;max-width:320px;overflow-wrap:anywhere}.ops-shell td:first-child{min-width:120px}.ops-actions{display:flex;gap:8px;flex-wrap:wrap;align-items:center}.ops-actions button{font-size:12px;padding:7px 10px;white-space:nowrap}.ops-state,.ops-badge{display:inline-block;background:#edf3eb;border-radius:6px;padding:3px 7px;font-size:12px;color:#365a42;white-space:nowrap}.ops-badge{background:#c67840;color:#fff}.ops-filters{display:flex;gap:12px;align-items:end;flex-wrap:wrap;margin-bottom:24px}.ops-shell label{display:grid;gap:7px;font-size:13px;color:#52665a}.ops-shell input,.ops-shell select,.ops-shell textarea{width:100%;min-width:0;border:1px solid #ced9ce;border-radius:8px;padding:10px 12px;background:white;color:#24312b}.ops-shell textarea{resize:vertical;min-height:80px}.ops-shell .ops-check{display:flex;align-items:center;gap:8px;min-height:42px}.ops-check input{width:16px;height:16px}.ops-pagination{display:flex;gap:8px;align-items:center;justify-content:end;margin-top:24px;font-size:12px;flex-wrap:wrap}.ops-pagination span{margin-right:auto;color:#66766a}.ops-empty{padding:40px 0;color:#66766a;text-align:center}.ops-alert,.ops-success{padding:14px 18px;border-radius:8px;line-height:1.6;font-size:14px;overflow-wrap:anywhere}.ops-alert{background:#fff0e9;color:#934a2b;border:1px solid #efd4c6}.ops-success{background:#e8f2e7;color:#315d3d}.ops-messages article{display:flex;gap:20px;align-items:center;justify-content:space-between;border-bottom:1px solid #e4e9e3;padding:20px 12px}.ops-messages article.unread{background:#f2f7ef;border-left:3px solid #47765a}.ops-messages small{display:block;color:#6c786e;margin:9px 0;font-size:12px}.ops-messages p{line-height:1.7;overflow-wrap:anywhere}.ops-detail .article-body{margin:30px 0;max-height:500px;overflow:auto}.ops-detail form{border-top:1px solid #e4e9e3;padding-top:20px}.ops-detail form .ops-actions{margin-top:14px}.ops-modal-backdrop{position:fixed;inset:0;background:#17271b70;display:grid;place-items:center;padding:20px;z-index:50}.ops-modal{background:white;border-radius:16px;padding:28px;width:100%;max-width:480px;max-height:90vh;overflow:auto}.ops-modal h2{font-size:20px;margin-top:0}.ops-modal form{display:grid;gap:18px}.ops-modal p{overflow-wrap:anywhere;line-height:1.7}.ops-shell button:hover{filter:brightness(.97)}
@media(max-width:1000px){.ops-main{padding:28px 22px}.ops-shell{grid-template-columns:180px minmax(0,1fr)}.ops-nav{padding:28px 16px}.ops-metrics{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media(max-width:640px){.ops-shell{display:block}.ops-nav{gap:16px;padding:20px;border-right:0;border-bottom:1px solid #dfe5df}.ops-brand span{display:none}.ops-nav nav{flex-direction:row;flex-wrap:wrap;gap:4px}.ops-nav nav a{padding:9px;font-size:13px}.ops-account{display:flex;align-items:center;flex-wrap:wrap;font-size:13px}.ops-account button{margin-left:auto}.ops-main{padding:24px 14px}.ops-card{padding:18px 14px}.ops-heading h1{font-size:25px}.ops-metrics{gap:10px}.ops-metrics article{padding:18px}.ops-messages article{display:block}.ops-messages article>.ops-actions{margin-top:10px}.ops-section-title{align-items:start}.ops-filters label{flex:1;min-width:120px}}
</style>
